package com.resumethinking.platform.matching;
import com.fasterxml.jackson.databind.ObjectMapper; import org.springframework.stereotype.Repository; import java.util.*;
@Repository public class JpaAnalysisResultRepository implements AnalysisResultRepository { private final AnalysisResultJpaRepository delegate; private final ObjectMapper mapper=new ObjectMapper().findAndRegisterModules(); public JpaAnalysisResultRepository(AnalysisResultJpaRepository delegate){this.delegate=delegate;} public AnalysisResult save(AnalysisResult r){try{delegate.save(new AnalysisResultEntity(r,mapper.writeValueAsString(r)));return r;}catch(Exception e){throw new IllegalStateException("result persistence failed",e);}} public Optional<AnalysisResult> findByTaskId(UUID id){return delegate.findByTaskId(id).map(e->{try{return mapper.readValue(e.getPayloadJson(),AnalysisResult.class);}catch(Exception x){return null;}}).filter(Objects::nonNull);} public long countByTaskId(UUID id){return delegate.findByTaskId(id).isPresent()?1:0;} }
